export const catalogOwnerQaId=n=>'10000000-0000-4000-8000-'+String(n).padStart(12,'0');
export const catalogOwnerQaItems=()=>['agreements','categories','organizations','sectors'].map(kind=>({kind,key:kind+':'+(kind==='categories'?'1':'')+':1',code:'1',label:'Opción sintética '+kind,agreementCode:kind==='categories'?'1':null,registrationAllowed:false}));
export function catalogOwnerQaAuthority(){return{version:'municipal-owner-catalog-authority.v1',scope:{tenantId:catalogOwnerQaId(1),membershipId:catalogOwnerQaId(2),bindingId:catalogOwnerQaId(3),companyId:101},authority:{version:'municipal-adoption-owner-authority.v1',policyVersion:'tenant-owner-adoption-policy.v1',policySha256:'3cd05ec553d4e19e511b4d755224efe36a470a02502704a621dec608ad312305',actor:{personId:catalogOwnerQaId(4),email:'owner-catalog@example.invalid',identityVersion:2,sessionId:catalogOwnerQaId(5),sessionVersion:3,releaseSha:'a'.repeat(40)}},policy:{version:OWNER_CATALOG_POLICY.version,sha256:OWNER_CATALOG_POLICY_SHA256},scopeVersion:'b'.repeat(64)};}
export async function catalogOwnerQaPreview(){const items=catalogOwnerQaItems(),v={version:'municipal-owner-catalog-preview.v1',decisionMode:'owner',independence:false,context:catalogOwnerQaAuthority(),proposal:{id:catalogOwnerQaId(6),requestSha256:'c'.repeat(64),baseVersion:'d'.repeat(64),baseItems:items,items:items.map(r=>({...r,label:r.label+' revisada'})),reason:'Preparación sintética completa',authorLabel:'Responsable sintético',createdAt:'2026-10-15T12:00:00+00:00'},itemsSha256:null,current:true};v.itemsSha256=await adoptionReviewHash(v.proposal.items);return{...v,previewSha256:await adoptionReviewHash(v)};}
